//! QCD reference formulas and benchmark quantities.
//!
//! **Authority boundary:** this module predates the executable lattice-gauge
//! program and contains a mixture of analytic asymptotics, phenomenological
//! models, constituent-quark estimates, chiral relations, and externally
//! sourced QCD/lattice reference values. None of the values in this file are
//! generated by a Symthaea lattice Monte Carlo calculation.
//!
//! Executable gauge-field calculations belong in the newer lattice-gauge
//! modules. Callers that need epistemic provenance should use the origin tags
//! below rather than inferring authority from this module's historical name.
//!
//! References:
//! - Wilson, K. G. (1974). Phys. Rev. D 10, 2445.
//! - Creutz, M. (1983). *Quarks, Gluons and Lattices*. Cambridge UP.
//! - Rothe, H. J. (2012). *Lattice Gauge Theories*. World Scientific.

use crate::constants::*;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum QcdValueOrigin {
    /// Analytic limiting/asymptotic expression, not a generated ensemble result.
    AnalyticModel,
    /// Phenomenological parametrization calibrated to QCD/hadron data.
    PhenomenologicalModel,
    /// Constituent-quark model estimate.
    ConstituentQuarkModel,
    /// Chiral/PCAC relation evaluated with approximate external inputs.
    ChiralRelation,
    /// Numerical value adopted from external lattice literature/consensus.
    ExternalLatticeReference,
    /// External QCD benchmark not established here as a lattice-only result.
    ExternalQcdReference,
    /// Reserved for values actually produced by a validated Symthaea lattice run.
    ComputedLattice,
}

impl QcdValueOrigin {
    pub const fn is_computed_lattice_output(self) -> bool {
        matches!(self, Self::ComputedLattice)
    }
}

#[derive(Debug, Clone, Copy, PartialEq)]
pub struct QcdReferenceQuantity {
    pub value: f64,
    pub units: &'static str,
    pub origin: QcdValueOrigin,
    pub note: &'static str,
}

/// Strong-coupling string-tension benchmark in GeV².
/// σ ≈ (440 MeV)² ≈ 0.194 GeV².
///
/// This is an adopted external benchmark, not a value computed by this crate.
pub const STRING_TENSION: f64 = 0.44 * 0.44;

pub const STRING_TENSION_REFERENCE: QcdReferenceQuantity = QcdReferenceQuantity {
    value: STRING_TENSION,
    units: "GeV^2",
    origin: QcdValueOrigin::ExternalLatticeReference,
    note: "adopted confinement/string-tension benchmark; not computed here",
};

/// Analytic area-law model for a rectangular Wilson loop.
///
/// At strong coupling: ⟨W(R,T)⟩ ~ exp(-σ R T). This function evaluates that
/// expression only; it does not measure a Wilson loop from an ensemble.
pub fn wilson_loop_area_law(r: f64, t: f64, sigma: f64) -> f64 {
    (-sigma * r * t).exp()
}

pub const fn wilson_loop_area_law_origin() -> QcdValueOrigin {
    QcdValueOrigin::AnalyticModel
}

/// Cornell phenomenological static quark-antiquark potential.
///
/// V(r) = -4α_s/(3r) + σr + C.
///
/// This is useful as a phenomenological reference curve. It is **not** a
/// potential extracted from Wilson loops generated by Symthaea.
pub fn cornell_potential(r_fm: f64) -> f64 {
    // Convert to GeV⁻¹: 1 fm = 5.068 GeV⁻¹
    let r = r_fm * 5.068;
    let alpha_s = 0.3; // phenomenological effective coupling at ~1 GeV scale
    let sigma = STRING_TENSION;
    let c = -0.25; // phenomenological constant offset (GeV)

    -4.0 * alpha_s / (3.0 * r) + sigma * r + c
}

pub const fn cornell_potential_origin() -> QcdValueOrigin {
    QcdValueOrigin::PhenomenologicalModel
}

/// Simplified constituent-quark mass estimate.
///
/// M_hadron ≈ Σ m_constituent + binding.
///
/// This is explicitly a constituent-quark model and must not be reported as a
/// lattice-QCD mass prediction.
pub fn hadron_mass_estimate(constituent_masses: &[f64], binding_gev: f64) -> f64 {
    constituent_masses.iter().sum::<f64>() + binding_gev
}

pub const fn hadron_mass_estimate_origin() -> QcdValueOrigin {
    QcdValueOrigin::ConstituentQuarkModel
}

/// Proton constituent-quark-model estimate.
pub fn proton_mass_constituent() -> f64 {
    3.0 * 0.336 // Three constituent quarks at ~336 MeV each
}

pub const fn proton_mass_constituent_origin() -> QcdValueOrigin {
    QcdValueOrigin::ConstituentQuarkModel
}

/// Pion mass scale from a PCAC/chiral relation with approximate inputs.
///
/// m_π² ≈ 2 m_q |⟨q̄q⟩| / f_π².
///
/// This illustrates pseudo-Goldstone physics; it is not an ensemble-derived
/// lattice pion mass.
pub fn pion_mass_pcac() -> f64 {
    let m_q = (M_UP + M_DOWN) / 2.0;
    let condensate = (0.25_f64).powi(3); // approximate |<qbar q>| in GeV^3
    let f_pi = 0.092; // approximate pion decay constant in GeV

    let m_pi_sq = 2.0 * m_q * condensate / (f_pi * f_pi);
    m_pi_sq.abs().sqrt()
}

pub const fn pion_mass_pcac_origin() -> QcdValueOrigin {
    QcdValueOrigin::ChiralRelation
}

/// Adopted crossover-temperature benchmark for physical quark masses.
pub const DECONFINEMENT_TEMPERATURE: f64 = 0.155; // GeV

pub const DECONFINEMENT_TEMPERATURE_REFERENCE: QcdReferenceQuantity = QcdReferenceQuantity {
    value: DECONFINEMENT_TEMPERATURE,
    units: "GeV",
    origin: QcdValueOrigin::ExternalLatticeReference,
    note: "adopted crossover-temperature reference; not computed here",
};

/// Adopted gluon-condensate benchmark.
///
/// This historical value is retained as a generic external QCD reference rather
/// than being labeled a Symthaea lattice result.
pub const GLUON_CONDENSATE: f64 = 0.012; // GeV^4

pub const GLUON_CONDENSATE_REFERENCE: QcdReferenceQuantity = QcdReferenceQuantity {
    value: GLUON_CONDENSATE,
    units: "GeV^4",
    origin: QcdValueOrigin::ExternalQcdReference,
    note: "historical external QCD condensate benchmark; provenance should be supplied by evidence layer",
};

/// Adopted topological-susceptibility scale χ_top ≈ (180 MeV)^4.
pub const TOPOLOGICAL_SUSCEPTIBILITY: f64 = 0.180_f64 * 0.180 * 0.180 * 0.180;

pub const TOPOLOGICAL_SUSCEPTIBILITY_REFERENCE: QcdReferenceQuantity = QcdReferenceQuantity {
    value: TOPOLOGICAL_SUSCEPTIBILITY,
    units: "GeV^4",
    origin: QcdValueOrigin::ExternalQcdReference,
    note: "external topological-susceptibility scale; not computed here",
};

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn legacy_reference_layer_never_self_labels_as_computed_lattice() {
        let origins = [
            STRING_TENSION_REFERENCE.origin,
            wilson_loop_area_law_origin(),
            cornell_potential_origin(),
            hadron_mass_estimate_origin(),
            proton_mass_constituent_origin(),
            pion_mass_pcac_origin(),
            DECONFINEMENT_TEMPERATURE_REFERENCE.origin,
            GLUON_CONDENSATE_REFERENCE.origin,
            TOPOLOGICAL_SUSCEPTIBILITY_REFERENCE.origin,
        ];
        assert!(origins.iter().all(|origin| !origin.is_computed_lattice_output()));
    }

    #[test]
    fn reference_origins_are_explicit() {
        assert_eq!(
            STRING_TENSION_REFERENCE.origin,
            QcdValueOrigin::ExternalLatticeReference
        );
        assert_eq!(
            cornell_potential_origin(),
            QcdValueOrigin::PhenomenologicalModel
        );
        assert_eq!(
            proton_mass_constituent_origin(),
            QcdValueOrigin::ConstituentQuarkModel
        );
        assert_eq!(pion_mass_pcac_origin(), QcdValueOrigin::ChiralRelation);
    }

    #[test]
    fn test_wilson_loop_area_law() {
        let w_small = wilson_loop_area_law(1.0, 1.0, STRING_TENSION);
        let w_large = wilson_loop_area_law(2.0, 2.0, STRING_TENSION);
        assert!(w_large < w_small, "Area law: larger loop = smaller W");
        assert!(w_small > 0.0 && w_small < 1.0);
    }

    #[test]
    fn test_cornell_potential_confining() {
        let v1 = cornell_potential(0.5);
        let v2 = cornell_potential(1.5);
        assert!(
            v2 > v1,
            "Confinement: V(1.5fm)={:.3} should > V(0.5fm)={:.3}",
            v2,
            v1
        );
    }

    #[test]
    fn test_cornell_potential_coulomb_short() {
        let v_short = cornell_potential(0.1);
        assert!(
            v_short < 0.0,
            "Short-range: V(0.1fm) = {:.3} should be negative",
            v_short
        );
    }

    #[test]
    fn test_proton_mass_model_scale() {
        let m_p = proton_mass_constituent();
        assert!(
            (m_p - M_PROTON).abs() < 0.1,
            "Proton model estimate = {:.3} GeV, reference {:.3}",
            m_p,
            M_PROTON
        );
    }

    #[test]
    fn test_pion_pseudo_goldstone_scale() {
        let m_pi = pion_mass_pcac();
        assert!(
            m_pi < 0.5 * M_PROTON,
            "Pion scale ({:.3} GeV) should be << proton ({:.3} GeV)",
            m_pi,
            M_PROTON
        );
    }
}
